def _canonical(value: object) -> bytes:
    text = json.dumps(
        value,
        allow_nan=False,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    )
    return (text + "\n").encode("utf-8")


def _sha256(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def _record(path: str, content: bytes) -> dict[str, object]:
    return {"path": path, "size": len(content), "sha256": _sha256(content)}


def _embedded(content: str) -> dict[str, object]:
    encoded = content.encode("utf-8")
    return {"content": content, "size": len(encoded), "sha256": _sha256(encoded)}


def _run_git(root: Path, *args: str) -> str:
    result = subprocess.run(
        ("git", *args),
        cwd=root,
        check=True,
        capture_output=True,
        text=True,
    )
    return result.stdout.strip()


def _assert_source_identity(root: Path) -> None:
    if root.is_symlink() or not root.is_dir():
        raise ValueError("R22 source root must be a regular directory")
    if _run_git(root, "rev-parse", "HEAD") != SOURCE_COMMIT:
        raise ValueError("R22 source commit drift")
    if _run_git(root, "rev-parse", "HEAD^{tree}") != SOURCE_TREE:
        raise ValueError("R22 source tree drift")
    if _run_git(root, "rev-parse", "R22-final^{commit}") != SOURCE_COMMIT:
        raise ValueError("R22-final tag drift")
    status = _run_git(root, "status", "--porcelain=v1", "--untracked-files=all")
    if status:
        raise ValueError("R22 source clone is not clean")


def _read_regular(path: Path, label: str) -> bytes:
    if path.is_symlink() or not path.is_file():
        raise ValueError(f"{label} must be a regular file")
    try:
        return path.read_bytes()
    except OSError as error:
        raise ValueError(f"cannot read {label}") from error


def _read_json(path: Path, label: str) -> dict[str, object]:
    content = _read_regular(path, label)
    try:
        value = json.loads(content.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError(f"invalid {label} JSON") from error
    if not isinstance(value, dict):
        raise ValueError(f"{label} must be a JSON object")
    return value


def _assert_collection_lock(
    lock_path: Path,
    manifests: Sequence[Path],
) -> tuple[str, bytes]:
    content = _read_regular(lock_path, "R22 collection lock")
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError as error:
        raise ValueError("R22 collection lock must be UTF-8") from error
    if not text.endswith("\n") or tuple(text.splitlines()) != tuple(
        sorted(text.splitlines(), key=str.casefold)
    ):
        raise ValueError("R22 collection lock is not canonical")
    digest = _sha256(content)
    for path in manifests:
        manifest = _read_json(path, "R22 collection manifest")
        if manifest.get("source_commit") != SOURCE_COMMIT:
            raise ValueError("R22 collection manifest commit drift")
        if manifest.get("lock_sha256") != digest:
            raise ValueError("R22 collection manifest lock drift")
    frozen = subprocess.run(
        (sys.executable, "-m", "pip", "freeze", "--exclude-editable"),
        check=True,
        capture_output=True,
        text=True,
    ).stdout.splitlines()
    if tuple(sorted(frozen, key=str.casefold)) != tuple(text.splitlines()):
        raise ValueError("active R22 interpreter differs from the collection lock")
    return text, content


def _archive_inputs(
    archive: Path,
    freeze_receipt: Path,
) -> tuple[dict[str, bytes], dict[str, object]]:
    receipt = _read_json(freeze_receipt, "R22 freeze receipt")
    expected_receipt = {
        "status": "PASS",
        "head_commit": SOURCE_COMMIT,
        "head_tree": SOURCE_TREE,
        "post_delivery_real_data_acceptance_status": "NOT_RUN",
    }
    if any(receipt.get(key) != value for key, value in expected_receipt.items()):
        raise ValueError("R22 freeze receipt identity drift")
    archive_content = _read_regular(archive, "R22 archive")
    if _sha256(archive_content) != receipt.get("archive_sha256"):
        raise ValueError("R22 archive hash drift")
    found: dict[str, bytes] = {}
    roots: set[str] = set()
    with tarfile.open(archive, "r:gz") as handle:
        for member in handle.getmembers():
            path = PurePosixPath(member.name)
            if len(path.parts) < 2:
                continue
            relative = PurePosixPath(*path.parts[1:]).as_posix()
            if relative not in INPUT_PATHS:
                continue
            if member.issym() or member.islnk() or not member.isfile():
                raise ValueError(f"R22 input is not a regular archive member: {relative}")
            stream = handle.extractfile(member)
            if stream is None or relative in found:
                raise ValueError(f"cannot uniquely read R22 input: {relative}")
            roots.add(path.parts[0])
            found[relative] = stream.read()
    if set(found) != set(INPUT_PATHS) or len(roots) != 1:
        raise ValueError("R22 archive does not contain the exact reference inputs")
    return found, receipt


def _materialize_inputs(root: Path, inputs: Mapping[str, bytes]) -> Path:
    examples = root / "xrr_fitter" / "examples"
    examples.mkdir(parents=True)
    for relative, content in inputs.items():
        target = root.joinpath(*PurePosixPath(relative).parts)
        target.write_bytes(content)
    return examples


def _json_value(value: object) -> object:
    if is_dataclass(value):
        return _json_value(asdict(value))
    if isinstance(value, Enum):
        return _json_value(value.value)
    if isinstance(value, np.ndarray):
        return _json_value(value.tolist())
    if isinstance(value, np.generic):
        return _json_value(value.item())
    if isinstance(value, complex):
        return {"real": float(value.real), "imag": float(value.imag)}
    if isinstance(value, Path):
        return value.name
    if isinstance(value, dict):
        return {str(key): _json_value(item) for key, item in value.items()}
    if isinstance(value, (tuple, list)):
        return [_json_value(item) for item in value]
    return value


def _numeric_policy(value: object) -> object:
    if isinstance(value, dict):
        return {
            "kind": "mapping",
            "fields": {key: _numeric_policy(item) for key, item in value.items()},
        }
    if isinstance(value, list):
        return {"kind": "sequence", "items": [_numeric_policy(item) for item in value]}
    if isinstance(value, float):
        return {"kind": "scalar_tolerance", "absolute": 1e-10, "relative": 1e-7}
    return "exact"


def _write_json(path: Path, value: object) -> bytes:
    content = _canonical(value)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)
    return content


def _npy_bytes(array: np.ndarray) -> bytes:
    stream = BytesIO()
    np.save(stream, np.asarray(array), allow_pickle=False)
    return stream.getvalue()


def _write_npz(path: Path, arrays: Mapping[str, np.ndarray]) -> bytes:
    path.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(path, "w", compression=zipfile.ZIP_STORED) as archive:
        for key in sorted(arrays):
            if not key.isidentifier():
                raise ValueError(f"invalid NPZ key: {key}")
            info = zipfile.ZipInfo(f"{key}.npy", date_time=(1980, 1, 1, 0, 0, 0))
            info.compress_type = zipfile.ZIP_STORED
            info.create_system = 3
            info.external_attr = 0o600 << 16
            info.flag_bits = 0
            info.extra = b""
            info.comment = b""
            archive.writestr(info, _npy_bytes(np.asarray(arrays[key])))
    return path.read_bytes()


def _load_runtime(examples: Path, source_root: Path) -> dict[str, object]:
    import xrr_core
    from xrr.data import read_xy
    from xrr.optimize import compile_fit_problem, encode_physical_vector, evaluate_jacobian, evaluate_vector
    from xrr.project import project_to_dict

    expected_core = (source_root / "xrr_fitter" / "xrr_core.py").resolve()
    if Path(xrr_core.__file__).resolve() != expected_core:
        raise ValueError("R22 runtime was not imported from the frozen source clone")
    cases: dict[str, object] = {}
    for stem in ("single-layer", "mo-si-periodic"):
        project_path = examples / f"{stem}.xrrproj.json"
        project = xrr_core.load_project(project_path)
        serialized = project_to_dict(project)
        source_document = json.loads(project_path.read_text(encoding="utf-8"))
        if serialized != source_document:
            raise ValueError(f"R22 project roundtrip drift: {stem}")
        dataset = project.datasets[0]
        data = read_xy(
            examples / f"{stem}.xy",
            dataset.beam,
            dataset.import_angle_offset_deg,
            dataset.column_mapping,
        )
        problem = compile_fit_problem(
            data,
            dataset.structure,
            dataset.instrument,
            project.fit_config,
            dataset.parameter_settings,
        )
        initial_unit = encode_physical_vector(problem, {})
        evaluation = evaluate_vector(problem, initial_unit)
        jacobian = evaluate_jacobian(problem, initial_unit)
        cases[stem] = {
            "project": project,
            "project_dict": serialized,
            "dataset": dataset,
            "data": data,
            "problem": problem,
            "initial_unit": initial_unit,
            "evaluation": evaluation,
            "jacobian": jacobian,
        }
    return cases


def _model_project(cases: Mapping[str, object]) -> dict[str, object]:
    from gui.main_window_batch_transition import with_batch_mode
    from gui.main_window_project_state import with_active_dataset

    single = cases["single-layer"]
    project = single["project"]
    dataset = single["dataset"]
    active = with_active_dataset(project, dataset.dataset_id)
    second = replace(dataset, dataset_id="single-layer-copy")
    batch_source = replace(project, datasets=(dataset, second))
    batch = with_batch_mode(batch_source, "joint")
    mask = tuple(index % 7 != 0 for index in range(len(dataset.fit_mask)))
    masked_dataset = replace(dataset, fit_mask=mask)
    masked = replace(project, datasets=(masked_dataset,))
    ui = replace(
        project,
        ui_state=replace(
            project.ui_state,
            active_dataset_id=dataset.dataset_id,
            expert_mode=True,
            workspace_splitter_sizes=(300, 700, 400),
            left_splitter_sizes=(260, 500),
            plot_tab_index=1,
        ),
    )
    return {
        "schema": "xrr-r22-model-project-reference-v1",
        "cases": {
            stem: {
                "project": case["project_dict"],
                "project_field_order": [
                    field.name for field in dataclass_fields(type(case["project"]))
                ],
                "dataset_field_order": [
                    field.name for field in dataclass_fields(type(case["dataset"]))
                ],
                "roundtrip_equal": True,
            }
            for stem, case in cases.items()
        },
        "transitions": {
            "active_dataset": _json_value(active.ui_state),
            "batch_mode": {
                "before": project.batch_mode,
                "after": batch.batch_mode,
                "dataset_ids": [item.dataset_id for item in batch.datasets],
            },
            "fit_mask": {
                "dataset_id": masked.datasets[0].dataset_id,
                "included": sum(masked.datasets[0].fit_mask),
                "excluded": len(masked.datasets[0].fit_mask) - sum(masked.datasets[0].fit_mask),
            },
            "ui_state": _json_value(ui.ui_state),
        },
    }


def _io(cases: Mapping[str, object]) -> tuple[dict[str, object], dict[str, np.ndarray]]:
    from xrr.data import DataColumnMapping, read_xy, with_fit_mask
    from xrr.project import load_project_file, project_to_dict, save_project

    summary: dict[str, object] = {}
    arrays: dict[str, np.ndarray] = {}
    prefixes = {"single-layer": "single", "mo-si-periodic": "mo_si"}
    for stem, case in cases.items():
        data = case["data"]
        prefix = prefixes[stem]
        summary[stem] = {
            "source_sha256": data.source_sha256,
            "raw_row_count": len(data.raw_rows),
            "raw_parse_status": list(data.raw_parse_status),
            "source_row_groups": _json_value(data.source_row_groups),
            "column_mapping": _json_value(data.column_mapping),
            "normalization": float(data.normalization),
            "r_floor": float(data.r_floor),
            "fit_ready": bool(data.fit_ready),
            "warnings": list(data.warnings),
        }
        arrays[f"{prefix}_fit_mask"] = data.fit_mask
        arrays[f"{prefix}_intensity_normalized"] = data.intensity_normalized
        arrays[f"{prefix}_intensity_raw"] = data.intensity_raw
        if data.intensity_sigma_raw is not None:
            arrays[f"{prefix}_intensity_sigma_raw"] = data.intensity_sigma_raw
        if data.intensity_sigma_normalized is not None:
            arrays[f"{prefix}_intensity_sigma_normalized"] = data.intensity_sigma_normalized
        arrays[f"{prefix}_qz_a_inv"] = data.qz_a_inv
        if data.resolution_raw is not None:
            arrays[f"{prefix}_resolution_raw"] = data.resolution_raw
        if data.sigma_q_a_inv is not None:
            arrays[f"{prefix}_sigma_q_a_inv"] = data.sigma_q_a_inv
        arrays[f"{prefix}_two_theta_deg"] = data.two_theta_deg
        arrays[f"{prefix}_validation_mask"] = data.validation_mask

    duplicate_content = b"0.100 10.0 1.0\n0.100 14.0 2.0\n0.200 5.0 1.0\n"
    generated = Path(cases["single-layer"]["data"].source_path).parent / "duplicate-reference.xy"
    generated.write_bytes(duplicate_content)
    duplicate_mapping = DataColumnMapping(two_theta=0, intensity=1, intensity_sigma=2)
    single_dataset = cases["single-layer"]["dataset"]
    duplicate = read_xy(
        generated,
        single_dataset.beam,
        single_dataset.import_angle_offset_deg,
        duplicate_mapping,
    )
    duplicate_mask = np.asarray([False, True], dtype=np.bool_)
    duplicate_masked = with_fit_mask(duplicate, duplicate_mask)
    arrays.update(
        {
            "duplicate_fit_mask": duplicate.fit_mask,
            "duplicate_fit_mask_after_transition": duplicate_masked.fit_mask,
            "duplicate_intensity_normalized": duplicate.intensity_normalized,
            "duplicate_intensity_raw": duplicate.intensity_raw,
            "duplicate_intensity_sigma_raw": duplicate.intensity_sigma_raw,
            "duplicate_qz_a_inv": duplicate.qz_a_inv,
            "single_fit_mask_after_transition": with_fit_mask(
                cases["single-layer"]["data"],
                np.asarray(
                    [index % 11 != 0 for index in range(cases["single-layer"]["data"].fit_mask.size)],
                    dtype=np.bool_,
                ),
            ).fit_mask,
        }
    )
    roundtrip: dict[str, bool] = {}
    with tempfile.TemporaryDirectory(prefix="xrr-r22-reference-project-roundtrip-") as directory:
        for stem, case in cases.items():
            path = Path(directory) / f"{stem}.json"
            save_project(case["project"], path)
            loaded = load_project_file(path)
            roundtrip[stem] = project_to_dict(loaded) == case["project_dict"]
    if not all(roundtrip.values()):
        raise ValueError("R22 project save/load roundtrip drift")
    return {
        "schema": "xrr-r22-io-reference-v1",
        "cases": summary,
        "duplicate_merge": {
            "input_sha256": _sha256(duplicate_content),
            "column_mapping": _json_value(duplicate_mapping),
            "raw_parse_status": list(duplicate.raw_parse_status),
            "source_row_groups": _json_value(duplicate.source_row_groups),
            "warnings": list(duplicate.warnings),
        },
        "project_roundtrip": roundtrip,
    }, arrays


def _physics(cases: Mapping[str, object]) -> tuple[dict[str, object], dict[str, np.ndarray]]:
    from xrr.physics import (
        _parratt_reflectivity_jacobian,
        _qz_from_theta_deg,
        abeles_reflectivity,
        footprint_factor,
        gaussian_smear,
        instrument_reflectivity,
        parratt_reflectivity,
        sld_depth_profile,
        theta_domain_smear,
    )
    from xrr.structure import expand_structure

    q_grid = np.linspace(0.005, 0.35, 128, dtype=np.float64)
    theta_grid = np.linspace(0.05, 2.5, 128, dtype=np.float64)
    summary: dict[str, object] = {}
    arrays: dict[str, np.ndarray] = {"q_grid": q_grid, "theta_grid": theta_grid}
    prefixes = {"single-layer": "single", "mo-si-periodic": "mo_si"}
    for stem, case in cases.items():
        dataset = case["dataset"]
        stack = expand_structure(dataset.structure, dataset.beam.wavelength_a)
        prefix = prefixes[stem]
        depth, profile = sld_depth_profile(stack, step_a=2.0)
        arrays[f"{prefix}_abeles"] = abeles_reflectivity(q_grid, stack)
        arrays[f"{prefix}_footprint"] = footprint_factor(theta_grid, 0.2)
        arrays[f"{prefix}_instrument"] = instrument_reflectivity(
            theta_grid,
            stack,
            dataset.beam,
            background=1e-8,
            relative_sigma=0.002,
        )
        arrays[f"{prefix}_parratt"] = parratt_reflectivity(q_grid, stack)
        arrays[f"{prefix}_q_resolution"] = gaussian_smear(
            q_grid,
            lambda values, current=stack: parratt_reflectivity(values, current),
            relative_sigma=0.002,
            absolute_sigma_a_inv=1e-4,
        )
        arrays[f"{prefix}_theta_resolution"] = theta_domain_smear(
            theta_grid,
            lambda values, current=stack, wavelength=dataset.beam.wavelength_a: parratt_reflectivity(
                _qz_from_theta_deg(values, wavelength), current
            ),
            sigma_theta_deg=0.01,
        )
        arrays[f"{prefix}_profile_depth"] = depth
        arrays[f"{prefix}_profile_sld_imag"] = profile.imag
        arrays[f"{prefix}_profile_sld_real"] = profile.real
        arrays[f"{prefix}_stack_roughness"] = stack.roughness_a
        arrays[f"{prefix}_stack_sld_imag"] = stack.sld_a2.imag
        arrays[f"{prefix}_stack_sld_real"] = stack.sld_a2.real
        arrays[f"{prefix}_stack_thickness"] = stack.thickness_a
        summary[stem] = {
            "thickness_a": stack.thickness_a.tolist(),
            "roughness_a": stack.roughness_a.tolist(),
            "sld_a2": _json_value(stack.sld_a2),
            "periodic_spans": _json_value(stack.periodic_spans),
        }

    stack = expand_structure(
        cases["single-layer"]["dataset"].structure,
        cases["single-layer"]["dataset"].beam.wavelength_a,
    )
    parameter_count = 3
    q_tangent = np.empty((q_grid.size, parameter_count), dtype=np.float64)
    q_tangent[:, 0] = np.linspace(2e-4, 8e-4, q_grid.size)
    q_tangent[:, 1] = np.linspace(-3e-4, 4e-4, q_grid.size)
    q_tangent[:, 2] = 1e-4
    thickness_tangent = np.zeros((stack.thickness_a.size, parameter_count), dtype=np.float64)
    sld_tangent = np.zeros((stack.sld_a2.size, parameter_count), dtype=np.complex128)
    roughness_tangent = np.zeros((stack.roughness_a.size, parameter_count), dtype=np.float64)
    if stack.thickness_a.size > 1:
        thickness_tangent[1, 0] = 0.7
    if stack.sld_a2.size > 1:
        sld_tangent[1, 1] = 1.1e-7 + 0.4e-8j
    roughness_tangent[:, 2] = np.linspace(0.02, 0.08, stack.roughness_a.size)
    derivative_primal, derivative = _parratt_reflectivity_jacobian(
        q_grid,
        stack,
        q_tangent,
        thickness_tangent,
        sld_tangent,
        roughness_tangent,
    )
    arrays.update(
        {
            "single_derivative_primal": derivative_primal,
            "single_parratt_jacobian": derivative,
            "single_tangent_qz": q_tangent,
            "single_tangent_roughness": roughness_tangent,
            "single_tangent_sld_imag": sld_tangent.imag,
            "single_tangent_sld_real": sld_tangent.real,
            "single_tangent_thickness": thickness_tangent,
        }
    )
    return {
        "schema": "xrr-r22-physics-reference-v1",
        "cases": summary,
        "derivative_case": {
            "case": "single-layer",
            "parameter_count": parameter_count,
            "primal_shape": list(derivative_primal.shape),
            "jacobian_shape": list(derivative.shape),
        },
    }, arrays


def _fit_compile(cases: Mapping[str, object]) -> tuple[dict[str, object], dict[str, np.ndarray]]:
    summary: dict[str, object] = {}
    arrays: dict[str, np.ndarray] = {}
    prefixes = {"single-layer": "single", "mo-si-periodic": "mo_si"}
    for stem, case in cases.items():
        problem = case["problem"]
        evaluation = case["evaluation"]
        jacobian = case["jacobian"]
        labels, counts = np.unique(problem.region_labels, return_counts=True)
        prefix = prefixes[stem]
        arrays[f"{prefix}_initial_model"] = evaluation.model_normalized
        arrays[f"{prefix}_initial_residual"] = evaluation.fit_log_residuals_decades
        arrays[f"{prefix}_initial_unit"] = case["initial_unit"]
        arrays[f"{prefix}_initial_weighted_residual"] = (
            evaluation.fit_weighted_residuals
        )
        arrays[f"{prefix}_jacobian"] = jacobian
        arrays[f"{prefix}_qz_a_inv"] = problem.data.qz_a_inv
        arrays[f"{prefix}_region_labels"] = problem.region_labels
        arrays[f"{prefix}_weights"] = problem.weights
        summary[stem] = {
            "parameter_definitions": _json_value(problem.parameter_definitions),
            "variables": _json_value(problem.variables),
            "parameter_order": [variable.name for variable in problem.variables],
            "bounds": [
                {
