                    "upper": float(definition.upper),
                    "initial": float(definition.initial),
                    "locked": bool(definition.locked),
                    "transform": definition.transform,
                }
                for definition in problem.parameter_definitions
            ],
            "region_counts": dict(zip(labels.tolist(), counts.tolist(), strict=True)),
            "weight_sum": float(np.sum(problem.weights)),
            "scale_prior_center": problem.scale_prior_center,
            "scale_prior_tau_decades": float(problem.scale_prior_tau_decades),
            "scale_prior_reason": problem.scale_prior_reason,
            "warnings": list(problem.warnings),
