            },
            "jacobian": {
                "shape": list(jacobian.shape),
                "finite": bool(np.all(np.isfinite(jacobian))),
                "frobenius_norm": float(np.linalg.norm(jacobian)),
                "max_abs": float(np.max(np.abs(jacobian))),
