def _reference_problem(
    case: Mapping[str, object],
    targets: set[str],
    master_seed: int,
) -> tuple[object, tuple[object, ...], object, np.ndarray]:
    from xrr.optimize import (
        FitConfig,
        ParameterSetting,
        SearchBudget,
        compile_fit_problem,
        encode_physical_vector,
    )

    base = case["problem"]
    settings = tuple(
        ParameterSetting(
            definition.name,
            definition.initial,
            definition.lower,
            definition.upper,
            locked=definition.name not in targets,
        )
        for definition in base.parameter_definitions
    )
    config = replace(
        FitConfig.fast(master_seed=master_seed),
        budget=SearchBudget(0, 0, 5, 1, 8),
        local_workers=1,
    )
    dataset = case["dataset"]
    problem = compile_fit_problem(
        case["data"],
        dataset.structure,
        dataset.instrument,
        config,
        settings,
    )
    return config, settings, problem, encode_physical_vector(problem, {})


