def _fit_search(cases: Mapping[str, object]) -> tuple[dict[str, object], dict[str, np.ndarray]]:
    from xrr.optimize import fit_dataset

    case = cases["single-layer"]
    config, settings, _problem, _initial = _reference_problem(
        case,
        {"component.0.thickness_a"},
        FIT_SEARCH_SEEDS[0],
    )
    dataset = case["dataset"]
    checkpoints: list[object] = []
    progress: list[object] = []
    result = fit_dataset(
        case["data"],
        dataset.structure,
        dataset.instrument,
        config,
        settings,
        progress=progress.append,
        checkpoint=checkpoints.append,
    )
    stage_d = next(checkpoint for checkpoint in checkpoints if checkpoint.stage == "D")
    resumed_checkpoints: list[object] = []
    resumed = fit_dataset(
        case["data"],
        dataset.structure,
        dataset.instrument,
        config,
        settings,
        checkpoint=resumed_checkpoints.append,
        resume_checkpoint=stage_d,
    )
    result_summary = _fit_result_summary(result)
    resumed_summary = _fit_result_summary(resumed)
    arrays: dict[str, np.ndarray] = {
        "region_labels": result.region_labels,
        "region_weights": result.region_weights,
    }
    for index, candidate in enumerate(result.candidates):
        prefix = f"candidate_{index:02d}"
        arrays[f"{prefix}_log_residuals"] = candidate.log_residuals_decades
        arrays[f"{prefix}_model"] = candidate.model_normalized
        arrays[f"{prefix}_qz_a_inv"] = candidate.qz_a_inv
        arrays[f"{prefix}_sld_depth"] = candidate.sld_depth_a
        arrays[f"{prefix}_sld_imag"] = candidate.sld_profile_a2.imag
        arrays[f"{prefix}_sld_real"] = candidate.sld_profile_a2.real
        arrays[f"{prefix}_unit"] = candidate.unit_vector
        arrays[f"{prefix}_weighted_residuals"] = candidate.weighted_residuals
    equivalent = result_summary == resumed_summary and all(
        np.array_equal(first.model_normalized, second.model_normalized, equal_nan=True)
        and np.array_equal(first.unit_vector, second.unit_vector, equal_nan=True)
        for first, second in zip(result.candidates, resumed.candidates, strict=True)
    )
    if not equivalent:
        raise ValueError("R22 Stage-D resume result drift")
    summary = {
        "schema": "xrr-r22-fit-search-reference-v1",
        "case": "single-layer",
        "progress": [_json_value(event) for event in progress],
        "checkpoints": [_checkpoint_summary(checkpoint) for checkpoint in checkpoints],
        "resumed_checkpoints": [
            _checkpoint_summary(checkpoint) for checkpoint in resumed_checkpoints
        ],
        "resume_equivalent": equivalent,
        "final_result": result_summary,
    }
    return summary, arrays


def _analysis(cases: Mapping[str, object]) -> tuple[dict[str, object], dict[str, np.ndarray]]:
    from xrr.optimize import McmcConfig, candidate_from_evaluation, evaluate_vector
    from xrr.uncertainty import (
        _build_problem_profile,
        bootstrap_problem_local,
        build_uncertainty_report,
        classify_result,
        run_problem_mcmc,
    )

    case = cases["mo-si-periodic"]
    _config, _settings, problem, center = _reference_problem(
        case,
        {
            "component.0.layer.0.thickness_a",
            "component.0.layer.1.thickness_a",
        },
        ANALYSIS_SEEDS[0],
    )
    evaluation = evaluate_vector(problem, center)
    candidate = candidate_from_evaluation(
        problem,
        center,
        evaluation,
        candidate_id="analysis-initial",
        seed_index=0,
        stop_reason="reference initial evaluation",
        nfev=1,
    )
    profile = _build_problem_profile(
        problem,
        center,
        "component.0.period_a",
    )
    bootstrap = bootstrap_problem_local(
        problem,
        candidate,
        sample_count=8,
        child_seed=ANALYSIS_SEEDS[1],
    )
    mcmc = run_problem_mcmc(
        problem,
        candidate,
        McmcConfig(walkers=6, burn_in=4, production_steps=8, thin=2),
        child_seed=ANALYSIS_SEEDS[2],
    )
    report = build_uncertainty_report(
        problem,
        (candidate,),
        profile_names=(),
        bootstrap=bootstrap,
    )
    report = replace(report, mcmc=mcmc)
    summary = {
        "schema": "xrr-r22-analysis-reference-v1",
        "case": "mo-si-periodic",
        "binary_profile": {
            "name": profile.name,
            "lower_closed": bool(profile.lower_closed),
            "upper_closed": bool(profile.upper_closed),
        },
        "bootstrap": {
            "parameter_names": list(bootstrap.parameter_names),
            "intervals": _json_value(bootstrap.intervals),
            "failure_rate": float(bootstrap.failure_rate),
        },
        "mcmc": {
            "config": _json_value(mcmc.config),
            "child_seed": int(mcmc.child_seed),
            "parameter_names": list(mcmc.parameter_names),
            "boundary_hits": list(mcmc.boundary_hits),
            "label": mcmc.label,
            "warnings": list(mcmc.warnings),
            "candidate_id": mcmc.candidate_id,
        },
        "report": {
            "candidate_id": report.candidate_id,
            "correlation_names": list(report.correlation_names),
            "strong_correlations": _json_value(report.strong_correlations),
            "systematic_residual": bool(report.systematic_residual),
            "residual_autocorrelation": bool(report.residual_autocorrelation),
            "boundary_hits": list(report.boundary_hits),
            "diagnostics": _json_value(report.diagnostics),
            "bootstrap_intervals": _json_value(report.bootstrap_intervals),
            "bootstrap_failure_rate": float(report.bootstrap_failure_rate),
        },
        "classification": _json_value(classify_result(problem, (candidate,), report)),
    }
    arrays = {
        "binary_profile_objectives": profile.objectives,
        "binary_profile_values": profile.values,
        "bootstrap_samples": bootstrap.samples,
        "mcmc_acceptance_fraction": mcmc.acceptance_fraction,
        "mcmc_effective_sample_size": mcmc.effective_sample_size,
        "mcmc_log_probability": mcmc.log_probability,
        "mcmc_samples_physical": mcmc.samples_physical,
        "mcmc_split_rhat": mcmc.split_rhat,
        "report_correlation_matrix": report.correlation_matrix,
    }
    return summary, arrays


def _service_project(
    case: Mapping[str, object],
    dataset_ids: Sequence[str],
    master_seed: int,
    target: str,
    batch_mode: str,
) -> object:
    from xrr.project import ParameterReference, ProjectUiState, SharingRule, XrrProject

    config, settings, _problem, _initial = _reference_problem(
        case,
        {target},
        master_seed,
    )
    datasets = tuple(
        replace(case["dataset"], dataset_id=dataset_id, parameter_settings=settings)
        for dataset_id in dataset_ids
    )
    sharing_rules = ()
    if batch_mode == "joint":
        sharing_rules = (
            SharingRule(
                "material.Mo.density_scale",
                tuple(ParameterReference(dataset_id, target) for dataset_id in dataset_ids),
            ),
        )
    return replace(
        XrrProject.new(datasets, master_seed=master_seed),
        fit_config=config,
        batch_mode=batch_mode,
        sharing_rules=sharing_rules,
        ui_state=ProjectUiState(active_dataset_id=dataset_ids[0]),
        base_directory=case["project"].base_directory,
    )


def _best_selections(project: object) -> object:
    selections = []
    for dataset in project.datasets:
        result = dataset.last_valid_result
        if result is None or result.best_index is None:
            raise ValueError(f"R22 service fit did not complete: {dataset.dataset_id}")
        candidate = result.candidates[result.best_index]
        selections.append((dataset.dataset_id, candidate.candidate_id))
    return replace(
        project,
        ui_state=replace(project.ui_state, selected_candidate_ids=tuple(selections)),
    )


def _checkpoint_project(project: object) -> dict[str, object]:
    datasets = []
    for dataset in project.datasets:
        checkpoint = dataset.checkpoint
        datasets.append(
            {
                "dataset_id": dataset.dataset_id,
                "stage": None if checkpoint is None else checkpoint.stage,
                "candidate_order": (
                    []
                    if checkpoint is None
                    else [candidate.candidate_id for candidate in checkpoint.candidates]
                ),
                "child_seeds": [] if checkpoint is None else list(checkpoint.child_seeds),
            }
        )
    return {"datasets": datasets}


def _project_fit_summary(
    result: object,
    progress: Sequence[object],
    checkpoints: Sequence[object],
) -> dict[str, object]:
    datasets = []
    for item in result.datasets:
        fit_result = item.fit_result
        if fit_result.best_index is None:
            raise ValueError(f"R22 service fit has no winner: {item.dataset_id}")
        datasets.append(
            {
                "dataset_id": item.dataset_id,
                "best_candidate_id": fit_result.candidates[
                    fit_result.best_index
                ].candidate_id,
                "fit_result": _fit_result_summary(fit_result),
            }
        )
    return {
        "mode": result.mode,
        "cancelled": bool(result.cancelled),
        "warnings": list(result.warnings),
        "dataset_order": [item.dataset_id for item in result.datasets],
        "sharing_rules": _json_value(result.updated_project.sharing_rules),
        "progress": [_json_value(item) for item in progress],
        "checkpoints": [_checkpoint_project(project) for project in checkpoints],
        "datasets": datasets,
    }


def _run_project_fit(project: object) -> tuple[object, object, list[object], list[object]]:
    import xrr_core

    progress: list[object] = []
    checkpoints: list[object] = []
    result = xrr_core.auto_fit(
        project,
        progress_callback=progress.append,
        checkpoint_callback=checkpoints.append,
    )
    fitted = _best_selections(result.updated_project)
    return result, fitted, progress, checkpoints


def _normalize_export_paths(content: bytes, project: object) -> bytes:
    base = Path(project.base_directory)
    roots = sorted(
        {str(base), str(base.resolve())},
        key=len,
        reverse=True,
    )
    normalized = content
    for root in roots:
        normalized = normalized.replace(
            root.encode("utf-8"),
            EXPORT_INPUT_ROOT_TOKEN.encode("utf-8"),
        )
    return normalized


def _normalized_export_file(
    path: Path,
    relative: str,
    project: object,
) -> dict[str, object]:
    original = path.read_bytes()
    content = _normalize_export_paths(original, project)
    record = _record(relative, content)
    if content != original:
        record["normalization"] = "input-root-token-v1"
    return record


def _normalized_xlsx(
    path: Path,
    relative: str,
    project: object,
) -> dict[str, object]:
    with zipfile.ZipFile(path) as archive:
        names = archive.namelist()
        if len(names) != len(set(names)) or "docProps/core.xml" not in names:
            raise ValueError(f"unexpected R22 XLSX members: {relative}")
        members = [
            _record(name, _normalize_export_paths(archive.read(name), project))
            for name in sorted(names)
            if name != "docProps/core.xml"
        ]
    return {
        "path": relative,
        "normalization": "zip-members-and-input-root-v1",
        "excluded_members": ["docProps/core.xml"],
        "members": members,
        "sha256": _sha256(_canonical(members)),
    }


def _export_summary(project: object) -> dict[str, object]:
    from xrr import _export_layout
    from xrr.export import export_project_result

    with tempfile.TemporaryDirectory(prefix="xrr-r22-reference-export-") as directory:
        output = Path(directory)
        token_hex = _export_layout.secrets.token_hex
        _export_layout.secrets.token_hex = lambda _size: EXPORT_TOKEN
        try:
            manifest = export_project_result(
                project,
                output,
                run_timestamp=EXPORT_TIMESTAMP,
            )
        finally:
            _export_layout.secrets.token_hex = token_hex
        run = manifest.run_directory
        root_files = [path.relative_to(run).as_posix() for path in manifest.root_files]
        datasets = [
            {
                "dataset_id": item.dataset_id,
                "directory": item.directory.relative_to(run).as_posix(),
                "files": [path.relative_to(run).as_posix() for path in item.files],
            }
            for item in manifest.datasets
        ]
        artifacts = []
        for path in manifest.files:
            relative = path.relative_to(run).as_posix()
            if path.suffix == ".xlsx":
                artifacts.append(_normalized_xlsx(path, relative, project))
            else:
                artifacts.append(_normalized_export_file(path, relative, project))
        if tuple(output.glob(".partial-*")):
            raise ValueError("R22 export left a partial directory")
        return {
            "timestamp": EXPORT_TIMESTAMP,
            "token": EXPORT_TOKEN,
            "manifest": {
                "run_directory": run.name,
                "root_files": root_files,
                "datasets": datasets,
            },
            "artifacts": sorted(artifacts, key=lambda item: str(item["path"])),
        }


def _invalidation_summary(project: object) -> dict[str, object]:
    import xrr_core

    dataset = project.datasets[0]
    source = Path(project.base_directory) / dataset.source_path
    with tempfile.TemporaryDirectory(prefix="xrr-r22-reference-invalidation-") as directory:
        isolated_source = Path(directory) / source.name
        isolated_source.write_bytes(source.read_bytes())
        isolated_dataset = replace(dataset, source_path=isolated_source.name)
        isolated = replace(
            project,
            datasets=(isolated_dataset,),
            base_directory=directory,
            ui_state=replace(
                project.ui_state,
                active_dataset_id=isolated_dataset.dataset_id,
                selected_candidate_ids=tuple(
                    selection
                    for selection in project.ui_state.selected_candidate_ids
                    if selection[0] == isolated_dataset.dataset_id
                ),
            ),
        )
        isolated_source.write_bytes(isolated_source.read_bytes() + b"# reference drift\n")
        validation = xrr_core.validate_project(isolated)
        invalidated = xrr_core.invalidate_changed_results(isolated, validation)
        if validation.valid or invalidated.datasets[0].last_valid_result is not None:
            raise ValueError("R22 source drift did not invalidate the fitted result")
        record = validation.datasets[0]
        return {
            "before": {
                "has_result": isolated.datasets[0].last_valid_result is not None,
                "has_checkpoint": isolated.datasets[0].checkpoint is not None,
                "selected_candidate_ids": _json_value(
                    isolated.ui_state.selected_candidate_ids
                ),
            },
            "validation": {
                "dataset_id": record.dataset_id,
                "status": _json_value(record.status),
                "expected_sha256": record.expected_sha256,
                "actual_sha256": record.actual_sha256,
                "message": record.message,
            },
            "after": {
                "has_result": invalidated.datasets[0].last_valid_result is not None,
                "has_checkpoint": invalidated.datasets[0].checkpoint is not None,
                "selected_candidate_ids": _json_value(
                    invalidated.ui_state.selected_candidate_ids
                ),
            },
            "declarations_preserved": {
                "source_path": invalidated.datasets[0].source_path
                == isolated.datasets[0].source_path,
                "source_sha256": invalidated.datasets[0].source_sha256
                == isolated.datasets[0].source_sha256,
            },
        }


