        "independent_workflow": _project_fit_summary(
            independent,
            independent_progress,
            independent_checkpoints,
        ),
        "joint_workflow": _project_fit_summary(
            joint,
            joint_progress,
            joint_checkpoints,
        ),
        "invalidation": _invalidation_summary(independent_fitted),
