                "plot_dataset_id": window.plot_panel.active_dataset_id(),
                "batch_mode": window.batch_mode_combo.currentData(),
                "fit_ready": window.fit_is_ready(),
                "fit_readiness": window.fit_readiness_text(),
                "dirty": window.is_dirty(),
                "expert_mode": window.project().ui_state.expert_mode,
                "workspace_splitter_sizes": window.workspace_splitter.sizes(),
                "left_splitter_sizes": window.left_splitter.sizes(),
                "plot_tab_index": window.plot_panel.current_tab_index(),
            }
            tab_titles = list(window.plot_panel.tab_titles())
            if not window.close():
                raise ValueError("R22 GUI window refused clean close")
            app.processEvents()
            action_trace.append({"action": "close", "visible": window.isVisible()})
            window.deleteLater()
            QCoreApplication.sendPostedEvents(None, QEvent.DeferredDelete)
            app.processEvents()
            deleted = not shiboken6.isValid(window)
            if not deleted:
                raise ValueError("R22 GUI window was not deleted")
            app.quit()
        return {
            "schema": "xrr-r22-gui-reference-v1",
            "runtime": "QApplication+MainWindow",
            "platform": "offscreen",
            "action_trace": action_trace,
            "action_states": action_states,
            "object_names": object_names,
            "tab_titles": tab_titles,
            "candidate_trace": candidate_trace,
            "workspace_trace": workspace_trace,
            "window_deleted": deleted,
            "real_data_acceptance": REAL_DATA_ACCEPTANCE,
        }
    finally:
        if previous_platform is None:
            os.environ.pop("QT_QPA_PLATFORM", None)
        else:
            os.environ["QT_QPA_PLATFORM"] = previous_platform


