def _npz_policy(arrays: Mapping[str, np.ndarray], tolerant: set[str]) -> dict[str, object]:
    return {
        "kind": "mapping",
        "fields": {
            key: ("physics_reflectivity" if key in tolerant else "array_equal")
            for key in sorted(arrays)
        },
    }


def _artifact_group(
    root: Path,
    group: str,
    json_value: object,
    arrays: Mapping[str, np.ndarray] | None,
    json_policy: object,
    input_ids: Sequence[str],
    tolerant_arrays: set[str] | None = None,
) -> tuple[dict[str, object], list[dict[str, object]]]:
    json_path = f"golden/{group}.json"
    json_content = _write_json(root / json_path, json_value)
    paths = [json_path]
    fields: dict[str, object] = {json_path: json_policy}
    records = [_record(json_path, json_content)]
    if arrays is not None:
        npz_path = f"golden/{group}.npz"
        npz_content = _write_npz(root / npz_path, arrays)
        paths.append(npz_path)
        fields[npz_path] = _npz_policy(arrays, tolerant_arrays or set())
        records.append(_record(npz_path, npz_content))
    entry = {
        "artifacts": paths,
        "comparison_policy": {"kind": "mapping", "fields": fields},
        "input_ids": list(input_ids),
    }
    return entry, records


def _build_artifacts(
    root: Path,
    cases: Mapping[str, object],
) -> tuple[dict[str, object], list[dict[str, object]]]:
    model = _model_project(cases)
    io_summary, io_arrays = _io(cases)
    physics_summary, physics_arrays = _physics(cases)
    compile_summary, compile_arrays = _fit_compile(cases)
    search_summary, search_arrays = _fit_search(cases)
    analysis_summary, analysis_arrays = _analysis(cases)
    services = _services(cases)
    gui = _gui(cases)
    values = {
        "model_project": (model, None, "exact", set()),
        "io": (io_summary, io_arrays, "exact", set()),
        "physics": (
            physics_summary,
            physics_arrays,
            "exact",
            {
                key
                for key in physics_arrays
                if key.endswith(
                    (
                        "_abeles",
                        "_derivative_primal",
                        "_instrument",
                        "_parratt",
                        "_q_resolution",
                        "_theta_resolution",
                    )
                )
            },
        ),
        "fit_compile": (
            compile_summary,
            compile_arrays,
            _numeric_policy(compile_summary),
            {key for key in compile_arrays if key.endswith("_initial_model")},
        ),
        "fit_search": (
            search_summary,
            search_arrays,
            _numeric_policy(search_summary),
            {key for key in search_arrays if key.endswith("_model")},
        ),
        "analysis": (
            analysis_summary,
            analysis_arrays,
            _numeric_policy(analysis_summary),
            set(),
        ),
        "services": (services, None, "exact", set()),
        "gui": (gui, None, "exact", set()),
    }
    groups: dict[str, object] = {}
    records: list[dict[str, object]] = []
    for group in GROUPS:
        value, arrays, policy, tolerant = values[group]
        entry, group_records = _artifact_group(
            root,
            group,
            value,
            arrays,
            policy,
            GROUP_INPUT_IDS[group],
            tolerant,
        )
        groups[group] = entry
        records.extend(group_records)
    return groups, sorted(records, key=lambda item: str(item["path"]))


def _provenance(
    generator_source: str,
    collection_lock: str,
    inputs: Mapping[str, bytes],
) -> dict[str, object]:
    input_classes = {
        ".xy": "bundled-example-data",
        ".json": "bundled-example-project",
    }
    records = []
    for path in sorted(inputs):
        content = inputs[path]
        stem = PurePosixPath(path).name.replace(".xrrproj.json", "-project").replace(".xy", "-data")
        suffix = ".json" if path.endswith(".json") else ".xy"
        records.append(
            {
                "input_id": stem,
                "input_class": input_classes[suffix],
                "path": path,
                "size": len(content),
                "sha256": _sha256(content),
            }
        )
    return {
        "schema": "xrr-r22-reference-provenance-v1",
        "source_commit": SOURCE_COMMIT,
        "source_tree": SOURCE_TREE,
        "generator": _embedded(generator_source),
        "collection_lock": _embedded(collection_lock),
        "python": {
            "implementation": platform.python_implementation(),
            "version": platform.python_version(),
        },
        "platform": {"system": platform.system(), "machine": platform.machine()},
        "inputs": records,
        "seeds": {
            "model_project": [],
            "io": [],
            "physics": [],
            "fit_compile": [],
            "fit_search": list(FIT_SEARCH_SEEDS),
            "analysis": list(ANALYSIS_SEEDS),
            "services": list(SERVICES_SEEDS),
            "gui": list(GUI_SEEDS),
        },
        "configurations": _configurations(),
        "real_data_acceptance": REAL_DATA_ACCEPTANCE,
    }


def _validate_output(output: Path) -> None:
    if output.parent.is_symlink() or not output.parent.is_dir():
        raise ValueError("sidecar output parent must be an existing regular directory")
    if output.exists() or output.is_symlink():
        raise ValueError("sidecar output must not already exist")


def build_sidecar(
    source_root: Path,
    archive: Path,
    freeze_receipt: Path,
    collection_lock: Path,
    collection_manifests: Sequence[Path],
    output: Path,
) -> None:
    _validate_output(output)
    _assert_source_identity(source_root)
    lock_text, _ = _assert_collection_lock(collection_lock, collection_manifests)
    inputs, _ = _archive_inputs(archive, freeze_receipt)
    generator_source = Path(__file__).read_text(encoding="utf-8")
    staging = Path(tempfile.mkdtemp(prefix=f".{output.name}.", dir=output.parent))
    try:
        with tempfile.TemporaryDirectory(prefix="xrr-r22-reference-inputs-") as directory:
            examples = _materialize_inputs(Path(directory), inputs)
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                cases = _load_runtime(examples, source_root)
                groups, artifacts = _build_artifacts(staging, cases)
        manifest = {
            "schema": "xrr-r22-reference-sidecar-v1",
            "provenance": _provenance(generator_source, lock_text, inputs),
            "groups": groups,
            "artifacts": artifacts,
        }
        _write_json(staging / "manifest.json", manifest)
        os.replace(staging, output)
    finally:
        if staging.exists():
            shutil.rmtree(staging)


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source-root", type=Path, required=True)
    parser.add_argument("--archive", type=Path, required=True)
    parser.add_argument("--freeze-receipt", type=Path, required=True)
    parser.add_argument("--collection-lock", type=Path, required=True)
    parser.add_argument("--collection-manifest", type=Path, action="append", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args(argv)
    build_sidecar(
        args.source_root,
        args.archive,
        args.freeze_receipt,
        args.collection_lock,
        tuple(args.collection_manifest),
        args.output,
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
